    INSERT (ID, COMPTE, LIBELLE, TYPECOMPTE, CLASSY, ANALYTIQUE_OBLI, IDJOURNAL, CODEIMPOT)
    VALUES (src.ID, src.COMPTE, src.LIBELLE, src.TYPECOMPTE, src.CLASSY, src.ANALYTIQUE_OBLI, src.IDJOURNAL, src.CODEIMPOT);

